import "server-only";
import { mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import path from "node:path";

/**
 * Where uploaded documents (contracts, акты) live. The database keeps only the metadata
 * (holding_files); the bytes go through this interface, so moving from the local disk to
 * Supabase Storage later changes one file. Keys are generated by the server (never taken
 * from the user), so they cannot point outside the storage root.
 */
export interface FileStorage {
  readonly name: "local" | "supabase";
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array | null>;
  /** Removes the bytes (only used for uploads that never became a document). Missing = fine. */
  delete(key: string): Promise<void>;
}

const KEY_RE = /^[a-z0-9-]+\/[a-f0-9-]{36}\.(pdf|jpg|png)$/;

export function assertSafeKey(key: string): void {
  if (!KEY_RE.test(key)) throw new Error("Invalid storage key");
}

/** Local disk under `.data/uploads` (ignored by git). Fine for local use and a single server. */
export class LocalFileStorage implements FileStorage {
  readonly name = "local" as const;
  constructor(private readonly root = path.join(process.cwd(), ".data", "uploads")) {}

  private pathFor(key: string): string {
    assertSafeKey(key);
    const full = path.resolve(this.root, key);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Invalid storage key");
    return full;
  }

  async put(key: string, bytes: Uint8Array): Promise<void> {
    const full = this.pathFor(key);
    await mkdir(path.dirname(full), { recursive: true });
    // "wx": never overwrite an existing document.
    await writeFile(full, bytes, { flag: "wx" });
  }

  async get(key: string): Promise<Uint8Array | null> {
    try {
      return new Uint8Array(await readFile(this.pathFor(key)));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }
  }

  async delete(key: string): Promise<void> {
    try {
      await unlink(this.pathFor(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
    }
  }
}

/**
 * Placeholder for Supabase Storage (private bucket, server-side service key). Not wired
 * up: it makes no network calls and refuses every operation until a developer implements
 * it and the founders add SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY themselves.
 */
export class SupabaseFileStorage implements FileStorage {
  readonly name = "supabase" as const;
  async put(): Promise<void> {
    throw new Error("Supabase Storage is not set up yet (FILE_STORAGE=supabase needs a developer)");
  }
  async get(): Promise<Uint8Array | null> {
    throw new Error("Supabase Storage is not set up yet (FILE_STORAGE=supabase needs a developer)");
  }
  async delete(): Promise<void> {
    throw new Error("Supabase Storage is not set up yet (FILE_STORAGE=supabase needs a developer)");
  }
}

/** Shown instead of the upload field, and the 503 message of the upload API, when uploads are off. */
export const UPLOADS_UNAVAILABLE_MESSAGE = "File uploads arrive with Supabase storage";

export interface UploadStatus {
  available: boolean;
  /** Why not (UPLOADS_UNAVAILABLE_MESSAGE) when unavailable. */
  message?: string;
}

/**
 * Can documents be uploaded here? In development: yes (local disk). In production only with a
 * storage that keeps files:
 * - `FILE_STORAGE` empty → off (the default local disk is not kept on Vercel, and on Vercel it
 *   is read-only: every upload would fail);
 * - `FILE_STORAGE=supabase` → off until the Supabase adapter is written (it is a placeholder);
 * - `FILE_STORAGE=local` → on, as an explicit choice for a server with its own lasting disk
 *   (or a local production test), but never on Vercel (`VERCEL=1`).
 */
export function fileUploadStatus(env: Record<string, string | undefined> = process.env): UploadStatus {
  if (override) return { available: true };
  if (env.NODE_ENV !== "production") return { available: true };
  const choice = env.FILE_STORAGE?.trim() || "";
  const working = choice === "local" && env.VERCEL !== "1";
  return working ? { available: true } : { available: false, message: UPLOADS_UNAVAILABLE_MESSAGE };
}

let override: FileStorage | null = null;

/** Tests point the storage at a temporary folder. */
export function setFileStorageForTests(storage: FileStorage | null): void {
  override = storage;
}

export function fileStorage(): FileStorage {
  if (override) return override;
  return process.env.FILE_STORAGE === "supabase" ? new SupabaseFileStorage() : new LocalFileStorage();
}

export function fileStorageByName(name: string): FileStorage {
  if (override && override.name === name) return override;
  return name === "supabase" ? new SupabaseFileStorage() : new LocalFileStorage();
}
